     1→/**
     2→ * FK Approved Contracts - Operations view for downloading approved contracts
     3→ */
     4→import React, { useState, useEffect } from 'react';
     5→import {
     6→  Box,
     7→  Typography,
     8→  Table,
     9→  TableBody,
    10→  TableCell,
    11→  TableContainer,
    12→  TableHead,
    13→  TableRow,
    14→  Paper,
    15→  Button,
    16→  Chip,
    17→  IconButton,
    18→  Tooltip,
    19→  Alert,
    20→  CircularProgress,
    21→  TableSortLabel,
    22→} from '@mui/material';
    23→import {
    24→  PictureAsPdf as PdfIcon,
    25→  Info as InfoIcon,
    26→  CheckCircle as CheckCircleIcon,
    27→} from '@mui/icons-material';
    28→import { operationsService } from '../../services/operationsService';
    29→import type { ContractGeneration, OperationsSortOrder } from '../../types/legal';
    30→
    31→// Mapping of frontend sort field names to backend database fields
    32→const SORT_FIELD_MAP: Record<string, string> = {
    33→  'contract_id': 'contract_id',
    34→  'contract_type': 'contract_type',
    35→  'nombre_importador': 'data_snapshot->nombre_importador',
    36→  'client_nit': 'client_nit',
    37→  'cupo_plataforma': 'data_snapshot->cupo_plataforma',
    38→  'reviewed_at': 'reviewed_at',
    39→};
    40→
    41→const FKApprovedContracts: React.FC = () => {
    42→  const [contracts, setContracts] = useState<ContractGeneration[]>([]);
    43→  const [loading, setLoading] = useState(true);
    44→  const [error, setError] = useState<string | null>(null);
    45→  const [downloadingId, setDownloadingId] = useState<string | null>(null);
    46→  const [sortBy, setSortBy] = useState<string>('reviewed_at');
    47→  const [sortOrder, setSortOrder] = useState<OperationsSortOrder>('desc');
    48→
    49→  const loadApprovedContracts = async () => {
    50→    try {
    51→      setLoading(true);
    52→      setError(null);
    53→      // Map frontend field name to backend field name
    54→      const backendSortField = SORT_FIELD_MAP[sortBy] || 'reviewed_at';
    55→      const data = await operationsService.getApprovedContracts(
    56→        undefined,
    57→        backendSortField,
    58→        sortOrder
    59→      );
    60→      setContracts(data);
    61→    } catch (err) {
    62→      console.error('Error loading approved contracts:', err);
    63→      setError('Error al cargar los contratos aprobados');
    64→    } finally {
    65→      setLoading(false);
    66→    }
    67→  };
    68→
    69→  useEffect(() => {
    70→    loadApprovedContracts();
    71→    // eslint-disable-next-line react-hooks/exhaustive-deps
    72→  }, [sortBy, sortOrder]);
    73→
    74→  const handleSortRequest = (column: string) => {
    75→    // If clicking the current sort column, toggle the order
    76→    if (sortBy === column) {
    77→      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    78→    } else {
    79→      // If clicking a new column, set it as the sort column with descending order
    80→      setSortBy(column);
    81→      setSortOrder('desc');
    82→    }
    83→  };
    84→
    85→  const handleDownloadPDF = async (contract: ContractGeneration) => {
    86→    if (!contract.approved_document_url) {
    87→      alert('No hay PDF disponible para este contrato');
    88→      return;
    89→    }
    90→
    91→    try {
    92→      setDownloadingId(contract.id);
    93→
    94→      // Download via backend API endpoint
    95→      const blob = await operationsService.downloadApprovedContractPdf(contract.id);
    96→      const url = window.URL.createObjectURL(blob);
    97→      const link = document.createElement('a');
    98→      link.href = url;
    99→      link.download = `contrato_${contract.contract_id}_aprobado.pdf`;
   100→      document.body.appendChild(link);
   101→      link.click();
   102→      document.body.removeChild(link);
   103→      window.URL.revokeObjectURL(url);
   104→    } catch (err) {
   105→      console.error('Error downloading PDF:', err);
   106→      alert('Error al descargar el PDF');
   107→    } finally {
   108→      setDownloadingId(null);
   109→    }
   110→  };
   111→
   112→  const formatDate = (dateString: string) => {
   113→    return new Date(dateString).toLocaleString('es-CO', {
   114→      year: 'numeric',
   115→      month: 'long',
   116→      day: 'numeric',
   117→      hour: '2-digit',
   118→      minute: '2-digit',
   119→    });
   120→  };
   121→
   122→  const formatCurrency = (amount: number) => {
   123→    return new Intl.NumberFormat('es-CO', {
   124→      style: 'currency',
   125→      currency: 'COP',
   126→      minimumFractionDigits: 0,
   127→    }).format(amount);
   128→  };
   129→
   130→  const getContractTypeBadge = (contractType: string) => {
   131→    if (contractType === 'otrosi') {
   132→      return {
   133→        label: 'Otrosí No. 1',
   134→        color: 'warning' as const,
   135→      };
   136→    }
   137→    if (contractType === 'inventario_bodega') {
   138→      return {
   139→        label: 'Inventario Bodega 3ro',
   140→        color: 'success' as const,
   141→      };
   142→    }
   143→    return {
   144→      label: 'Activos',
   145→      color: 'info' as const,
   146→    };
   147→  };
   148→
   149→  if (loading) {
   150→    return (
   151→      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 300 }}>
   152→        <CircularProgress />
   153→      </Box>
   154→    );
   155→  }
   156→
   157→  if (error) {
   158→    return <Alert severity="error">{error}</Alert>;
   159→  }
   160→
   161→  if (contracts.length === 0) {
   162→    return (
   163→      <Alert severity="info" icon={<InfoIcon />}>
   164→        No hay contratos aprobados disponibles para descarga.
   165→      </Alert>
   166→    );
   167→  }
   168→
   169→  return (
   170→    <Box>
   171→      <Box sx={{ mb: 3, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
   172→        <Typography variant="h6" sx={{ fontWeight: 600 }}>
   173→          Contratos Aprobados ({contracts.length})
   174→        </Typography>
   175→        <Button
   176→          variant="outlined"
