                        checked={filters.contract_types?.includes('activos') || false}
                        onChange={(e) => handleContractTypeChange('activos', e.target.checked)}
                      />
                    }
                    label={<Chip label="Activos" color="info" size="small" />}
                  />
                  <FormControlLabel
                    control={
                      <Checkbox
